import {
  getNavigationAllowlist,
  isPathAllowedByAllowlist,
} from 'config/navigationAllowlist';
import { sanitizeInternalNavigationSearch } from 'domain/Filter/FilterRegistry/utils/sanitizeInternalNavigationSearch';

const isUnsafePathname = (pathname: string): boolean =>
  pathname.startsWith('//') ||
  pathname.includes('://') ||
  pathname.includes('\\') ||
  /%2f%2f/i.test(pathname);

const parseInternalUrl = (path: string): URL | null => {
  if (!path.startsWith('/') || path.startsWith('//')) return null;

  try {
    const url = new URL(path, window.location.origin);
    if (url.origin !== window.location.origin) return null;
    if (isUnsafePathname(url.pathname)) return null;

    return url;
  } catch {
    return null;
  }
};

export const isSafeInternalPath = (path: string): boolean =>
  parseInternalUrl(path) !== null;

export type SafeLocation = { pathname: string; search: string };

export const resolveSafeLocation = (
  pathname: string,
  search: string,
  allowlist: readonly string[] = getNavigationAllowlist(),
): SafeLocation | null => {
  if (!isSafeInternalPath(pathname)) return null;
  if (!isPathAllowedByAllowlist(pathname, allowlist)) return null;

  const rawSearch = search.startsWith('?') ? search.slice(1) : search;
  const safeSearch = sanitizeInternalNavigationSearch(
    new URLSearchParams(rawSearch),
  );

  return { pathname, search: safeSearch };
};

export const resolveSafeTabNavigationTarget = (params: {
  baseRoute: string;
  tabId: string;
  tabIds: readonly string[];
  searchParams: URLSearchParams;
  filterHidden: boolean;
}): SafeLocation | null => {
  const { baseRoute, tabId, tabIds, searchParams, filterHidden } = params;
  if (!tabIds.includes(tabId)) return null;

  const pathname = `${baseRoute}/${tabId}`;
  const search = filterHidden
    ? ''
    : sanitizeInternalNavigationSearch(searchParams);

  return resolveSafeLocation(pathname, search);
};
